"""Access prices from the internal pricing service."""

import json
import os
import urllib.request

# The service was moved; allow deployments to override this when its address
# changes again.  PRICING_KEY is supplied by the runtime secret configuration.
BASE = os.environ.get(
    "PRICING_URL", "http://pricing-v2.internal:8081/api/v2/price"
)


def get_price(sku: str) -> float:
    headers = {}
    key = os.environ.get("PRICING_KEY")
    if key:
        headers["X-Pricing-Key"] = key
    request = urllib.request.Request(
        f"{BASE.rstrip('/')}/{sku}", headers=headers
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    """Return the sum of the current service prices for *skus*."""
    return sum(get_price(sku) for sku in skus)
